            double p = 2.4994305002802721e-08;
            p = p * r + 2.7632293277020833e-07;
            p = p * r + 2.7557622530418205e-06;
            p = p * r + 2.4801486521436422e-05;
            p = p * r + 1.9841269432679901e-04;
